"""A tiny Caesar cipher utility."""


def encrypt(text: str, shift: int) -> str:
    """Return *text* with each alphabetic character shifted by *shift* positions."""
    result = []
    shift = shift % 26

    for char in text:
        if "a" <= char <= "z":
            shifted = (ord(char) - ord("a") + shift) % 26 + ord("a")
            result.append(chr(shifted))
        elif "A" <= char <= "Z":
            shifted = (ord(char) - ord("A") + shift) % 26 + ord("A")
            result.append(chr(shifted))
        else:
            result.append(char)

    return "".join(result)
